submit:fail409.tree:
body
  div#crShell
    div#crHero
      h1#crHeroTitle {Короткий профиль}
      p#crHeroSub {Несколько полей — и вы можете продолжить в приложении со всеми функциями.} <Приглашение от <strong class="cr-hero-trainer-name">Анна Соколова</strong>. Заполните поля — и продолжите в приложении.>
    div#crFormCard
      div
        label {Телефон}
        div
          input#crPhone
        span#crPhoneError.cr-error--visible {Ошибка 409}
      div
        label {Имя}
        input#crFirstName
        span#crFirstNameError
      div#crLastNameBlock
        label {Фамилия (необязательно)}
        input#crLastName
    div#crGlobalError
    div#crActions
      button#crBtnSubmit
        span {Продолжить}
    div#crSuccessScreen
      p#crSuccessSub {Профиль сохранён.}
      button#crBtnOpenHome {Открыть «Главная»}

